/**
 * Allows the user to supply one or more sizes that are used to search for structures that have
 * that size.
 */
public class FindStructuresBySizeAction : FindDataTypesBySizeAction {

	/* @SuppressWarnings("hiding") */
	public static readonly string NAME = "Find Structures by Size";

	public FindStructuresBySizeAction(DataTypeManagerPlugin plugin, string menuSubGroup) : base(plugin, NAME, menuSubGroup)
    {
		setHelpLocation(new HelpLocation("DataTypeManagerPlugin", "Find_Structures_By_Size"));
	}

	/* @Override */
	protected GTreeFilter createFilter(SortedRangeList values) {
		return new StructureSizeGTreeFilter(values);
	}

	private class StructureSizeGTreeFilter : GTreeFilter {

		private SortedRangeList sizes;

		StructureSizeGTreeFilter(SortedRangeList sizes) {
			this.sizes = sizes;
		}

		/* @Override */
		public bool showFilterMatches() {
			return true;
		}

		/* @Override */
		public bool acceptsNode(GTreeNode node) {
			if (!(node is DataTypeNode)) {
				return false;
			}
			DataTypeNode dataTypeNode = (DataTypeNode) node;
			DataType dataType = dataTypeNode.getDataType();
			if (!(dataType is Structure)) {
				return false;
			}

			Structure structure = (Structure) dataType;
			int length = structure.getLength();
			if (structure.isZeroLength()) {
				length = 0;
			}

			foreach (Range range in sizes) {
				if (range.contains(length)) {
					return true;
				}
			}

			return false;
		}
	}
}
